{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"LA Rent Stabilization Ordinance allowable rent increases","requirement":"A landlord may raise RSO rent only once every 12 months by LAHD's allowable percentage; since February 2, 2026 utility increases and the extra 10% for a dependent are barred, and increases were banned from March 30, 2020 to January 31, 2024.","key_value":"one increase every 12 months at the allowable rent increase percentage","coverage_conditions":"Rental properties first built on or before October 1, 1978, plus replacement units: apartments, condominiums, townhomes, duplexes, two or more single-family units on one parcel, long-term hotel or rooming-house rooms, units attached to commercial buildings, ADUs, JADUs, mobile homes.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"The rent amount is not regulated for condominium or townhome tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)"]},"exemptions":"Condominium and townhome tenancies commenced after December 31, 1995 (rent not regulated); units granted the luxury exemption based on rent charged on or before May 31, 1978; temporary exemptions.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO legal reasons for eviction and no-fault relocation","requirement":"Under the RSO a landlord may terminate a tenancy only for the listed at-fault or no-fault reasons, must file every termination notice with LAHD within three business days of serving the tenant, and must pay relocation assistance for no-fault evictions.","key_value":"30-day and 60-day written notice; relocation assistance for no-fault evictions","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":2,"note":null}

